    if n % 15 == 0:
        return 'FizzBuzz'
    if n % 3 == 0:
        return 'Fizz'
    if n % 5 == 0:
        return 'Buzz'
    return str(n)


def second_largest(xs):
    u = sorted(set(xs))
    return u[-2] if len(u) >= 2 else None


def word_freq(s):
    d = {}
    for w in s.lower().split():
        d[w] = d.get(w, 0) + 1
    return d
